// ---------------------------------------------------------------------------
// Author re-assignment
//
// Posts whose primary category is one of the four «technical» verticals
// below are signed by the secondary editor (`SECONDARY_AUTHOR_*`) so
// the blog’s author distribution looks like an editorial team rather
// than a single-author content farm. We mutate the array in place
// (rather than threading the second author through every literal in
// `BLOG_POSTS`) to keep the diff small — the `author` field is no
// longer the source of truth for who wrote a given post; this block
// is. Reassign here, never inside the literal entries.
//
// Roadmap reference: B4 in `pikart-roadmap-to-1.md` (E-E-A-T multi-
// author signal). Numberland-style: distinct knowsAbout per author so
// Google can model two related but non-identical Person entities.
// ---------------------------------------------------------------------------
const SECONDARY_AUTHOR_CATEGORIES = new Set<string>([
  'developer-tools',
  'cloud-storage',
  'ai-writing-seo',
  'productivity-work',
])
for (const post of BLOG_POSTS) {
  if (SECONDARY_AUTHOR_CATEGORIES.has(post.primaryCategorySlug)) {
    post.author = SECONDARY_AUTHOR_NAME
    post.authorUrl = SECONDARY_AUTHOR_URL
    post.authorSameAs = getSecondaryAuthorSameAs()
  }
}

export const BLOG_SLUGS = BLOG_POSTS.map((p) => p.slug)

export function findBlogPost(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find((p) => p.slug === slug)
}

/**
 * Count "words" inside a Persian blog post body.
 *
 * Persian / Arabic don't have a hard word boundary the way English
 * does (Persian uses ZWNJ inside many compound words, e.g.
 * «می‌خواهم»), so we tokenise on Unicode whitespace AND on the
 * zero-width non-joiner. Numbers, English brand names, and
 * punctuation are kept since Google itself counts them.
 *
 * Includes:
 *   - excerpt (counts as the dek/lede summary)
 *   - every section's heading + body paragraphs + bullets
 *   - FAQ questions/answers (rendered inline on the page)
 *   - HowTo step names + bodies
 *
 * Used by `articleLd()` to emit `BlogPosting.wordCount` and to
 * derive `timeRequired = PT{wordCount/220}M`. Both fields are
 * recommended by Google's Article rich-result docs and are part
 * of the AI-Overviews / Top-Stories candidate-selection signals.
 */
export function computeBlogWordCount(post: BlogPost): number {
  const chunks: string[] = []
  if (post.excerpt) chunks.push(post.excerpt)
  for (const section of post.sections) {
    if (section.heading) chunks.push(section.heading)
    if (section.body) chunks.push(...section.body)
    if (section.bullets) chunks.push(...section.bullets)
    if (section.cta?.label) chunks.push(section.cta.label)
  }
  if (post.faq) {
    for (const item of post.faq) {
      chunks.push(item.question, item.answer)
    }
  }
  if (post.howToSteps) {
    for (const step of post.howToSteps) {
      chunks.push(step.name, step.text)
    }
  }
  let total = 0
  for (const chunk of chunks) {
    if (!chunk) continue
    // Strip the inline `[anchor](slug)` markdown so we don't count
    // the anchor URL twice (once for the visible label, once for
    // the slug). Keep only the visible label.
    const visible = chunk.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    // Tokens: collapse all whitespace + ZWNJ runs into a single
    // separator, then split. Empty tokens are dropped.
    const tokens = visible
      .replace(/[\u200c\u200d]/g, ' ')
      .split(/\s+/u)
      .filter(Boolean)
    total += tokens.length
  }
  return total
}

/** Sort newest first by `datePublished` for the index. */
export function getBlogPostsSorted(): BlogPost[] {
  return [...BLOG_POSTS].sort((a, b) => b.datePublished.localeCompare(a.datePublished))
}

/**
 * Find blog posts that mention the given service slug — either as the
 * primary subject (`primaryServiceSlug`) or as a related entry. Used
 * by `ServiceDetailPage` to surface a «مقالات مرتبط» section on every
 * service page that has matching coverage in the blog. Posts are
 * deduplicated and returned sorted newest-first; pass `limit` to cap
 * the result count.
 */
export function getRelatedBlogPostsForService(
  slug: string,
  limit?: number,
): BlogPost[] {
  if (!slug) return []
  const seen = new Set<string>()
  const results: BlogPost[] = []
  // Pass 1: posts where this slug is the primary subject — strongest
  // semantic match, surface them first.
  for (const post of getBlogPostsSorted()) {
    if (post.primaryServiceSlug === slug && !seen.has(post.slug)) {
      seen.add(post.slug)
      results.push(post)
    }
  }
  // Pass 2: posts where this slug appears in `relatedServiceSlugs`.
  for (const post of getBlogPostsSorted()) {
    if (
      post.relatedServiceSlugs &&
      post.relatedServiceSlugs.includes(slug) &&
      !seen.has(post.slug)
    ) {
      seen.add(post.slug)
      results.push(post)
    }
  }
  if (limit != null && limit >= 0) return results.slice(0, limit)
  return results
}
